questions.solution:
import numpy as np


def standardise_rows(x):
    """Return x with every row shifted to mean 0 and scaled to standard deviation 1."""
    centred = x - np.mean(x, axis=1, keepdims=True)
    return centred / np.std(x, axis=1, keepdims=True)

def broadcast_shape(left, right):
    """Return the shape NumPy gives two operands of these shapes, or raise ValueError."""
    # Rule 1: left-pad the shorter shape with 1s until both have the same length.
    ndim = max(len(left), len(right))
    left = (1,) * (ndim - len(left)) + tuple(left)
    right = (1,) * (ndim - len(right)) + tuple(right)
    result = []
    for m, n in zip(left, right):
        # Rule 2: two aligned sizes must be equal, or one of them must be 1.
        if m != n and m != 1 and n != 1:
            raise ValueError(f"sizes {m} and {n} differ and neither is 1")
        # Rule 3: a size of 1 stretches to the other size.
        result.append(n if m == 1 else m)
    return tuple(result)


def broadcast_shapes(*shapes):
    """Return the broadcast shape of any number of shapes, or raise ValueError."""
    result = ()                                  # the shape of a scalar: compatible with everything
    for shape in shapes:
        result = broadcast_shape(result, shape)  # fold each shape into the running result
    return result

questions.tests:
import itertools

import numpy as np

assert broadcast_shapes() == ()
assert broadcast_shapes((3, 4)) == (3, 4)
assert broadcast_shapes((8, 1, 6, 1), (7, 1, 5)) == (8, 7, 6, 5)
assert broadcast_shapes((3, 1), (3,), (2, 1, 1)) == (2, 3, 3)
assert broadcast_shapes((300, 3), (1, 3), (3,), ()) == (300, 3)
for bad in [((3, 3), (2, 3)), ((5, 3), (5,)), ((2, 1), (3,), (4,))]:
    try:
        broadcast_shapes(*bad)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for " + str(bad))

# Every triple of shapes with 0 to 2 axes of size 1, 2 or 3, against NumPy.
small = [shape for ndim in range(3) for shape in itertools.product((1, 2, 3), repeat=ndim)]
for trio in itertools.product(small, repeat=3):
    try:
        expected = np.broadcast_shapes(*trio)
    except ValueError:
        expected = "error"
    try:
        got = broadcast_shapes(*trio)
    except ValueError:
        got = "error"
    assert got == expected, (trio, got, expected)
print("all tests passed")
